<?php if($error):?><p class="error" role="alert"><?=h($error)?></p><?php endif;?><form method="post" class="login-panel wide"><?=csrfField()?><?php foreach(['company_ru'=>'Название RU','company_en'=>'Company EN','address_ru'=>'Адрес RU','address_en'=>'Address EN','hours_ru'=>'Часы работы RU','hours_en'=>'Opening hours EN','phone'=>'Телефон / Phone','email'=>'Email','latitude'=>'Широта / Latitude','longitude'=>'Долгота / Longitude'] as $field=>$label):?><label><?=h($label)?><input name="<?=$field?>" required maxlength="180" <?php if($field==='email'):?>type="email"<?php elseif($field==='phone'):?>type="tel" pattern="\+?[0-9 ()\-]{7,25}"<?php elseif(in_array($field,['latitude','longitude'],true)):?>type="number" step="0.0000001" min="<?=$field==='latitude'?-90:-180?>" max="<?=$field==='latitude'?90:180?>"<?php endif;?> value="<?=h($row[$field]??'')?>"></label><?php endforeach;?><button class="button"><?=t('Сохранить','Save')?></button></form>
